Step-by-Step bug reproduction script


```typescript
//bugReproduction.ts

import type { Proof } from '@cashu/cashu-ts';
import { getDecodedToken, getEncodedToken } from './packages/core';
import { MemoryKeyRingRepository } from './packages/core/repositories/memory/MemoryKeyRingRepository.ts';
import { KeyRingService } from './packages/core/services/KeyRingService.ts';
import { SeedService } from './packages/core/services/SeedService.ts';


const MOCK_SEED = new Uint8Array(64);

for (let i = 0 ; i< 64; i++) {
    MOCK_SEED[i] = i;
}

const repo = new MemoryKeyRingRepository();
const seedService = new SeedService(async () => MOCK_SEED);
const keyRingService = new KeyRingService(repo, seedService);

const proof:Proof = {
    id:'009a1f2b3c4d5e6f',
    amount: 100,
    secret: 'test-secret-for-p2pk',
    C: '02abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890',
};

// Bug

async function main() {
    console.log('='.repeat(60));
    console.log('BUG REPRODUCTION TEST')
    console.log('='.repeat(60));

    //gen key  
    const keypair = await keyRingService.generateNewKeyPair({dumpSecretKey: true});
    const pubkey = keypair.publicKeyHex;

    console.log('\n Generated keypair');
    console.log(' Public Key:', pubkey.substring(0,16) + '...');

    //sign
    console.log('\n--step 1: sign proof --- ' );
    const signed = await keyRingService.signProof(proof,pubkey);

    console.log('witness type:', typeof signed.witness);
    console.log('witness', signed.witness);

    //reproduction Bug

    if(typeof signed.witness === 'string') { //before FIX path 
        console.error('BUG: witness is string (should be object)');
    } else {
        console.log('FIXED: witness is object'); //FIXED path
    }

    //DB save simul 

    console.log('\n---step 2:save to db---');
    const witnessJson = signed.witness ? (typeof signed.witness === 'string' ? signed.witness : JSON.stringify(signed.witness))
    : null;
    /* 
    ProofRepository.ts:60  (sqlite3)
    const witnessJson = p.witness ? JSON.stringify(p.witness) : null;
    */
    console.log('witnessJson:', witnessJson);

    // token Encoding

    console.log('\n--- Step 3:Encode Token---');
    const token = getEncodedToken({
        mint: 'https://mint.exmaple.com',
        proofs:[signed],
        unit:'sat',
    });

    console.log('token:', token);

    // decode Token
    console.log('\n --- step 4: decode token ---');
    const decoded = getDecodedToken(token);

    console.log('witness:', decoded.proofs[0].witness);
    console.log('witness type:', typeof decoded.proofs[0].witness);

    //verify sign
    console.log('\n ---step 5: verify signature ---');

    //@cashu/cashu-ts return witness as 'string' (spec)
    // JSON.parse needed
    const witnessObj = typeof decoded.proofs[0].witness === 'string'
        ? JSON.parse(decoded.proofs[0].witness as string)
        : decoded.proofs[0].witness;
    const signatures = witnessObj?.signatures;
    console.log('witness.signatures:', signatures);

    // final confirmation

    console.log('\n' + '='.repeat(60));
    if (Array.isArray(signatures) && signatures.length > 0) {
        console.log('SUCCESS: P2PK signatures found!');
        console.log('   Signature:', signatures[0].substring(0,32) + '...');
    } else {
        console.error(' FAILED: No sigantures found');
        console.log('   This means the witness was double-encoded');
    }
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

```

